/**
 * The notes store: one plain-text file per note under
 * `.dsh-notes/<sessionId>/` in the session's workspace.
 *
 * A note belongs to one conversation, so the conversation is a directory level
 * rather than a field inside the files: deleting a conversation's notes is
 * deleting one directory, and no file can drift into the wrong conversation.
 *
 * The file name is the note's identity and its creation time:
 * `<epoch-ms>-<8 hex>.txt`. A note's text is the whole file, so the format
 * stays something a text editor can read — that is what "plain txt" means here.
 *
 * Ordering is by creation time, newest first. The name carries it, so copying
 * or editing a file never resorts the list the way an mtime would.
 */
import { mkdir, readdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises'
import { randomBytes } from 'node:crypto'
import { join } from 'node:path'
import { MAX_NOTE_BYTES, describe } from './protocol.js'

/** The directory, relative to the session workspace, holding one directory per Session. */
const DIRECTORY = '.dsh-notes'

/** A note file name; group 1 is the creation time in epoch milliseconds. */
const FILE_NAME = /^(\d{13})-[0-9a-f]{8}\.txt$/

/** A note identity as the client sends it back. */
const NOTE_ID = /^\d{13}-[0-9a-f]{8}$/

/** The only Session id shapes this store turns into a directory name. */
const SESSION_NAME = /^[0-9A-Za-z][0-9A-Za-z._-]*$/

/** Distinguishes same-millisecond writes from this process to one note. */
let temporarySequence = 0

/**
 * Whether one Session id can name a directory in this store.
 *
 * The id reaching here has already been resolved against the Host's own stores,
 * so this is the second lock, not the first: it keeps a path segment a segment
 * whatever the resolution above ever grows into.
 * @param {unknown} sessionId - session identity.
 * @returns {boolean} true when the id is usable as a directory name.
 */
export function isStoreName(sessionId) {
  return typeof sessionId === 'string' && sessionId.length <= 128 && SESSION_NAME.test(sessionId)
}

/**
 * The notes directory of one Session.
 * @param {string} root - canonical workspace root.
 * @param {string} sessionId - validated session identity.
 * @returns {string} absolute directory path.
 */
export function notesDirectory(root, sessionId) {
  return join(root, DIRECTORY, sessionId)
}

/**
 * Stat one path as a regular file.
 * @param {string} path - absolute path.
 * @returns {Promise<import('node:fs').Stats | undefined>} the stat, or undefined
 *   when it is absent or not a regular file.
 */
async function statRegular(path) {
  try {
    const info = await stat(path)
    return info.isFile() ? info : undefined
  } catch (error) {
    if (error?.code === 'ENOENT' || error?.code === 'ENOTDIR') return undefined
    throw error
  }
}

/**
 * Every note of one Session, newest first.
 * @param {string} root - workspace root.
 * @param {string} sessionId - session identity.
 * @returns {Promise<Array<{ id: string, text: string, createdAt: number }>>} the notes.
 */
export async function listNotes(root, sessionId) {
  const directory = notesDirectory(root, sessionId)
  let names
  try {
    names = await readdir(directory)
  } catch (error) {
    // The directory appears with the first note; a conversation without notes
    // has none.
    if (error?.code === 'ENOENT' || error?.code === 'ENOTDIR') return []
    throw error
  }

  const notes = []
  for (const name of names) {
    const match = FILE_NAME.exec(name)
    if (match === null) continue
    const path = join(directory, name)
    const info = await statRegular(path)
    if (info === undefined || info.size > MAX_NOTE_BYTES) continue
    const text = await readFile(path, 'utf8')
    notes.push({ id: name.slice(0, -'.txt'.length), text, createdAt: Number(match[1]) })
  }

  notes.sort((left, right) => right.createdAt - left.createdAt || right.id.localeCompare(left.id))
  return notes
}

/**
 * How many notes one Session holds.
 *
 * Same admission rules as {@link listNotes} — a name that does not match, or a
 * file that is not a regular text file of a legal size, is not a note — but
 * without reading a single byte of content.
 * @param {string} root - workspace root.
 * @param {string} sessionId - session identity.
 * @returns {Promise<number>} the count, zero for a conversation with no notes.
 */
export async function countNotes(root, sessionId) {
  const directory = notesDirectory(root, sessionId)
  let names
  try {
    names = await readdir(directory)
  } catch (error) {
    if (error?.code === 'ENOENT' || error?.code === 'ENOTDIR') return 0
    throw error
  }

  let count = 0
  for (const name of names) {
    if (FILE_NAME.exec(name) === null) continue
    const info = await statRegular(join(directory, name))
    if (info === undefined || info.size > MAX_NOTE_BYTES) continue
    count += 1
  }
  return count
}

/**
 * Refuse a note text this store cannot hold.
 * @param {unknown} text - complete note content.
 * @returns {{ code: string, message: string } | undefined} the refusal, if any.
 */
function checkText(text) {
  if (typeof text !== 'string') return { code: 'bad-request', message: 'text must be a string.' }
  const bytes = Buffer.byteLength(text, 'utf8')
  if (bytes > MAX_NOTE_BYTES) {
    return {
      code: 'too-large',
      message: `That note is ${Math.round(bytes / 1024)} KiB; the limit is ${Math.round(MAX_NOTE_BYTES / 1024)} KiB.`,
    }
  }
  return undefined
}

/**
 * Create one note with the text the composer started it with.
 * @param {string} root - workspace root.
 * @param {string} sessionId - session identity.
 * @param {unknown} text - the note's opening text; empty when the caller has none.
 * @returns {Promise<{ value?: { id: string, text: string, createdAt: number }, code?: string, message?: string }>}
 *   `{ value }` on success, or `{ code, message }` on refusal.
 */
export async function createNote(root, sessionId, text = '') {
  const refusal = checkText(text)
  if (refusal !== undefined) return refusal

  const createdAt = Date.now()
  const id = `${createdAt}-${randomBytes(4).toString('hex')}`
  const directory = notesDirectory(root, sessionId)
  await mkdir(directory, { recursive: true })
  // `wx` fails instead of overwriting, so a collision can never eat a note.
  await writeFile(join(directory, `${id}.txt`), text, { encoding: 'utf8', flag: 'wx' })
  return { value: { id, text, createdAt } }
}

/**
 * Remove one note.
 * @param {string} root - workspace root.
 * @param {string} sessionId - session identity.
 * @param {unknown} id - note identity.
 * @returns {Promise<{ value?: { id: string }, code?: string, message?: string }>}
 *   `{ value }` on success, or `{ code, message }` on refusal.
 */
export async function removeNote(root, sessionId, id) {
  if (typeof id !== 'string' || !NOTE_ID.test(id)) {
    return { code: 'bad-request', message: 'id must be a note identity.' }
  }
  const path = join(notesDirectory(root, sessionId), `${id}.txt`)
  try {
    await rm(path)
  } catch (error) {
    if (error?.code === 'ENOENT') return { code: 'not-found', message: 'That note no longer exists.' }
    throw error
  }
  return { value: { id } }
}

/**
 * Replace one note's text.
 * @param {string} root - workspace root.
 * @param {string} sessionId - session identity.
 * @param {unknown} id - note identity.
 * @param {unknown} text - complete new content.
 * @returns {Promise<{ value?: { id: string, text: string, createdAt: number }, code?: string, message?: string }>}
 *   `{ value }` on success, or `{ code, message }` on refusal.
 */
export async function saveNote(root, sessionId, id, text) {
  if (typeof id !== 'string' || !NOTE_ID.test(id)) {
    return { code: 'bad-request', message: 'id must be a note identity.' }
  }
  const refusal = checkText(text)
  if (refusal !== undefined) return refusal

  const directory = notesDirectory(root, sessionId)
  const path = join(directory, `${id}.txt`)
  const before = await statRegular(path)
  if (before === undefined) return { code: 'not-found', message: 'That note no longer exists.' }

  // Same-directory temporary file, then a rename: a failed save leaves the note
  // as it was rather than half-written.
  const temporary = `${path}.tmp-${process.pid}-${Date.now()}-${temporarySequence++}`
  await writeFile(temporary, text, 'utf8')
  try {
    await rename(temporary, path)
  } catch (error) {
    await rm(temporary, { force: true }).catch(() => {})
    return { code: 'io-error', message: describe(error) }
  }
  return { value: { id, text, createdAt: Number(id.slice(0, 13)) } }
}
